1	import type { PageThreeConfig } from "../../../types/core.types.js";
2	import type { AboutInitialState } from "../../../types/about.types.js";
3	import * as THREE from "three";
4	import { getDefaultThreeConfig } from "../../../config/base.config.js";
5	import {
6	  aboutLights,
7	  aboutBackground,
8	  astronaut,
9	  earth,
10	  gravityBalls,
11	  jetEngine,
12	  rocket,
13	  terrian,
14	} from "../../../core/setup.js";
15	import {
16	  ABOUT_DEFAULT_SCENE_STATE,
17	  cloneAboutSceneState,
18	} from "../theatre/AboutSceneState.js";
19	import type {
20	  AboutPageConfig,
21	  AboutSceneSectionKey,
22	  AboutTheatreSheetId,
23	} from "../../../types/about.types.js";
24	import type {
25	  PageSceneRuntimePolicy,
26	  SceneBackgroundPolicy,
27	  SceneProgressOptionsMap,
28	  SceneSelectorMap,
29	} from "../../../types/runtime.types.js";
30	import { TextReveal } from "../../../animation/TextReveal.js";
31	import { runIntroDomTimeline } from "../../../runtime/IntroLoadingRuntime.js";
32	import {
33	  BACKGROUND_APP_DOM as APP_MANAGER_DOM,
34	  CONTACT_HEAD_TRANSITION,
35	} from "../../../config/transition.config.js";
36	import {
37	  resolveAboutAuthorMode,
38	  resolveAboutPreviewMode,
39	} from "../theatre/AboutTheatreConfig.js";
40	
41	const aboutIntroOverlay = { tl: runIntroDomTimeline };
42	let didRunAboutDomInit = false;
43	const ABOUT_IS_AUTHOR_MODE = resolveAboutAuthorMode();
44	const ABOUT_IS_THEATRE_PREVIEW_MODE = resolveAboutPreviewMode();
45	const ABOUT_HERO_SLOGAN_SELECTOR =
46	  '.no-sub-about-hero-slogan[data-scene="heroSlogan"]';
47	const ABOUT_HERO_SLOGAN_ALPHA_MIN = 0.24;
48	const ABOUT_HERO_SLOGAN_ALPHA_MAX = 0.88;
49	const ABOUT_HERO_SLOGAN_ALPHA_SPAN =
50	  ABOUT_HERO_SLOGAN_ALPHA_MAX - ABOUT_HERO_SLOGAN_ALPHA_MIN;
51	const ABOUT_HERO_SLOGAN_ALPHA_PROPERTY = "--hero-slogan-surface-alpha";
52	const ABOUT_JOURNEY_SURFACE_SELECTOR = ".no-sub-about-journey-surface";
53	const ABOUT_JOURNEY_SURFACE_ALPHA_MIN = 0.24;
54	const ABOUT_JOURNEY_SURFACE_ALPHA_MAX = 0.72;
55	const ABOUT_JOURNEY_SURFACE_ALPHA_PROPERTY = "--about-journey-surface-alpha";
56	const ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN =
57	  (ABOUT_JOURNEY_SURFACE_ALPHA_MAX - ABOUT_JOURNEY_SURFACE_ALPHA_MIN) / 3;
58	const ABOUT_CONTACT_SECTION_SELECTOR = '.no-main-contact[data-scene="contact"]';
59	const ABOUT_CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
60	const ABOUT_CONTACT_ACTIONS_SELECTOR = ".no-main-contact__actions";
61	let aboutHeroSloganElement: HTMLElement | null = null;
62	let aboutJourneySurfaceElement: HTMLElement | null = null;
63	const aboutSceneDomState = {
64	  isContactHeadVisible: false,
65	  contactHeadTimers: [] as number[],
66	};
67	
68	const aboutBaselineSceneState = cloneAboutSceneState(ABOUT_DEFAULT_SCENE_STATE);
69	const defaultThree = getDefaultThreeConfig();
70	
71	function getAboutHeroSloganElement(): HTMLElement | null {
72	  if (aboutHeroSloganElement?.isConnected) {
73	    return aboutHeroSloganElement;
74	  }
75	  aboutHeroSloganElement = document.querySelector<HTMLElement>(
76	    ABOUT_HERO_SLOGAN_SELECTOR,
77	  );
78	  return aboutHeroSloganElement;
79	}
80	
81	function getAboutJourneySurfaceElement(): HTMLElement | null {
82	  if (aboutJourneySurfaceElement?.isConnected) {
83	    return aboutJourneySurfaceElement;
84	  }
85	  aboutJourneySurfaceElement = document.querySelector<HTMLElement>(
86	    ABOUT_JOURNEY_SURFACE_SELECTOR,
87	  );
88	  return aboutJourneySurfaceElement;
89	}
90	
91	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
92	  const element = getAboutHeroSloganElement();
93	  if (!element) return;
94	  const clampedProgress = Math.max(0, Math.min(1, progress));
95	  const alpha =
96	    ABOUT_HERO_SLOGAN_ALPHA_MIN +
97	    ABOUT_HERO_SLOGAN_ALPHA_SPAN * clampedProgress;
98	  element.style.setProperty(ABOUT_HERO_SLOGAN_ALPHA_PROPERTY, alpha.toFixed(4));
99	}
100	
101	function resetAboutHeroSloganSurfaceAlpha(): void {
102	  const element = getAboutHeroSloganElement();
103	  if (!element) return;
104	  element.style.setProperty(
105	    ABOUT_HERO_SLOGAN_ALPHA_PROPERTY,
106	    String(ABOUT_HERO_SLOGAN_ALPHA_MIN),
107	  );
108	}
109	
110	function setAboutJourneySurfaceAlpha(alpha: number): void {
111	  const element = getAboutJourneySurfaceElement();
112	  if (!element) return;
113	  element.style.setProperty(ABOUT_JOURNEY_SURFACE_ALPHA_PROPERTY, alpha.toFixed(4));
114	}
115	
116	function syncAboutMissionVisionSurfaceAlpha(progress: number): void {
117	  const clampedProgress = Math.max(0, Math.min(1, progress));
118	  const alpha =
119	    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
120	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
121	  setAboutJourneySurfaceAlpha(alpha);
122	}
123	
124	function syncAboutServicesSurfaceAlpha(progress: number): void {
125	  const clampedProgress = Math.max(0, Math.min(1, progress));
126	  const alpha =
127	    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
128	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN +
129	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
130	  setAboutJourneySurfaceAlpha(alpha);
131	}
132	
133	function syncAboutAwardsSurfaceAlpha(progress: number): void {
134	  const clampedProgress = Math.max(0, Math.min(1, progress));
135	  const alpha =
136	    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
137	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * 2 +
138	    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
139	  setAboutJourneySurfaceAlpha(alpha);
140	}
141	
142	function resetAboutJourneySurfaceAlpha(): void {
143	  setAboutJourneySurfaceAlpha(ABOUT_JOURNEY_SURFACE_ALPHA_MIN);
144	}
145	
146	function clearTimers(timerIds: number[]): number[] {
147	  timerIds.forEach((timerId) => {
148	    window.clearTimeout(timerId);
149	  });
150	  return [];
151	}
152	
153	
154	function syncAboutContactHead(progress: number): void {
155	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
156	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
157	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
158	  if (!section || !head || !actions) return;
159	
160	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
161	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
162	
163	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
164	  aboutSceneDomState.isContactHeadVisible = shouldShow;
165	  aboutSceneDomState.contactHeadTimers = clearTimers(
166	    aboutSceneDomState.contactHeadTimers,
167	  );
168	
169	  if (shouldShow) {
170	    section.dataset.active = "true";
171	    head.dataset.active = "true";
172	    actions.dataset.active = "true";
173	    TextReveal.setVisibleOff(textItems);
174	    textItems.forEach((item, index) => {
175	      const timerId = window.setTimeout(() => {
176	        TextReveal.setVisibleOn(item);
177	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
178	      aboutSceneDomState.contactHeadTimers.push(timerId);
179	    });
180	    return;
181	  }
182	
183	  textItems.forEach((item) => {
184	    TextReveal.setVisibleOff(item);
185	  });
186	  section.dataset.active = "false";
187	  head.dataset.active = "false";
188	  actions.dataset.active = "false";
189	}
190	
191	function disposeAboutContactHead(): void {
192	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
193	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
194	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
195	  if (!section || !head || !actions) return;
196	
197	  aboutSceneDomState.isContactHeadVisible = false;
198	  aboutSceneDomState.contactHeadTimers = clearTimers(
